#!/usr/bin/env python3
"""Render saved C1/C2 measurements without rerunning or selecting workloads."""
import json,statistics
from pathlib import Path
root=Path(__file__).resolve().parent
read=lambda p:json.loads((root/p).read_text())
suites=['regression-c','embench','mibench-evaluation','polybench']
policies=['c1-greedy','c1-global','c1-weighted']
ablations=[r['variant'] for r in read('results/frozen/c1-ablations.json')['variants']]
lines=['# C1/C2 numerical evidence','',
    'Generated by `python3 report-results.py` from preserved run JSON. '
    'Ratios greater than one mean improvement. MiBench includes diagnostic-invalid `bf` in structural totals. '
    'Only the baseline-valid functional subset is an acceptance gate. No runtime speedup is inferred.','']
def table(headers,rows):
    lines.extend(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|'])
    lines.extend('| '+' | '.join(map(str,row))+' |' for row in rows);lines.append('')
lines.extend(['## C1 family and ablations','',
    'Each policy/suite link contains every per-program result and per-function measurement, '
    'including entry jumps, body jumps, eligible edges and both fall-through rates.',''])
rows=[]
for v in ['measured-'+p for p in policies]+ablations:
    for s in suites:
        path=f'results/{v}/{s}-comparison.json';d=read(path);a=d['aggregate']
        assert d['correctness_gate_pass']
        rows.append([f'[{v}/{s}]({path})',
            f"{a['baseline_Lgoto_count']} → {a['optimized_Lgoto_count']}",
            f"{a['baseline_fallthrough_rate']:.6f} → {a['optimized_fallthrough_rate']:.6f}",
            f"{a['R_jump_geomean']:.6f}",f"{a['R_size_geomean']:.6f}",
            f"{a['optimized_loop_weighted_fallthrough_rate']:.6f}",a['function_jump_regressions']])
table(['Policy / suite','Lgoto','Fall-through rate','GM R_jump','GM R_size','Weighted fall-through','Functions with more jumps'],rows)
lines.extend(['## Primary C1 per-program results','',
    '`R_jump=(1+B)/(1+C)`; `R_size=B_text/C_text`. Null percentage change for a zero baseline is shown as “—”.',''])
for s in suites:
    lines.extend(['### '+s,'']);rows=[]
    for r in read(f'results/measured-c1-global/{s}-comparison.json')['programs']:
        rows.append([r['program'],f"{r['baseline_Lgoto_count']} → {r['optimized_Lgoto_count']}",
            '—' if r['jump_relative_change'] is None else f"{100*r['jump_relative_change']:+.2f}%",
            f"{r['baseline_fallthrough_rate']:.6f} → {r['optimized_fallthrough_rate']:.6f}",
            f"{r['baseline_text_bytes']} → {r['optimized_text_bytes']}",
            f"{r['optimized_text_ratio']:.6f}",f"{r['R_jump']:.6f}",f"{r['R_size']:.6f}",
            'PASS' if r['functional_pass'] else 'Diagnostic baseline + candidate FAIL'])
    table(['Program','Lgoto','Change','Fall-through','Text bytes','C/B text','R_jump','R_size','Functional'],rows)
lines.extend(['## C2 experimental clone results','',
    'Reference is C1-global. These emitted executables have no proved original-to-cloned-LTL preservation theorem. '
    'The native certificate and runtime tests pass; they are not a formal equivalence proof.',''])
for s in ['regression-c','embench','polybench']:
    path=f'results/c2-checked-prototype/{s}/summary.json';d=read(path);rs=d['programs']
    assert all(r['compiled'] and r['functional_pass'] and not r['formal_C_to_output_proof'] for r in rs)
    lines.extend(['### '+s,'',f'[Raw results]({path}): {len(rs)} compiled and passed; '
        f"Lgoto {sum(r['before_Lgoto'] for r in rs)} → {sum(r['after_Lgoto'] for r in rs)}; "
        f"GM R_size {statistics.geometric_mean(r['baseline_text_bytes']/r['text_bytes'] for r in rs):.6f}.",''])
    table(['Program','Lgoto','Clones','Copied LTL instructions','Text bytes','C2/C1 text'],[
        [r['name'],f"{r['before_Lgoto']} → {r['after_Lgoto']}",r['clones'],r['copied_LTL_instructions'],
         f"{r['baseline_text_bytes']} → {r['text_bytes']}",f"{r['text_bytes']/r['baseline_text_bytes']:.6f}"] for r in rs])
(root/'RESULTS.md').write_text('\n'.join(lines)+'\n')
print('Wrote RESULTS.md: all C1 policies/ablations, 85 primary C1 and 73 C2 program rows')
